  { s: 'h2in', a: [352, 450, 396, 450], sc: 1 },
  { s: 'protons', a: [502, 315, 546, 315], sc: 1 },
  { s: 'protons', a: [502, 440, 546, 440], sc: 1 },
  { s: 'wire', a: [402, 208, 402, 142], sc: 1 },
  { s: 'wire', a: [602, 142, 602, 208], sc: 1 },
  { s: 'unused', a: [312, 540, 192, 540], sc: 0 },
  { s: 'o2', a: [792, 265, 722, 265], sc: 0 },
  { s: 'water', a: [730, 535, 774, 535], sc: 0 },
  { s: 'water', a: [668, 452, 668, 500], sc: 0 },
  { s: 'cathodeRxn', a: [640, 373, 662, 373], sc: 0 }
];

function buildArrows() {
  KEYS.forEach(function (k) { S[k].arrows.clear(); });
  var w = state.rate <= 0 ? 0 : 3.5 + 6.5 * state.rate / 100;
  var col = state.clean ? '#3a3a3a' : '#ffffff';
  ARROWS.forEach(function (d) {
    var ww = d.sc ? w : 8;
    if (ww <= 0) return;
    arrow(S[d.s].arrows, d.a[0], d.a[1], d.a[2], d.a[3], ww, col);
  });
  if (state.rate > 0) {
    var cw = Math.max(4, w * 0.8);
    S.h2in.arrows.path('M312,268 Q346,274 351,288').fill('none')
      .stroke({ color: col, width: cw, linecap: 'round' });
    S.h2in.arrows.polygon([[351, 308], [341, 288], [361, 288]]).fill(col);
  }
}

/* ---------- labels ---------- */
var FS = 27;
label(gLabels, 502, 34, 'Electric power', FS, 'middle');
label(gLabels, 142, 273, 'Hydrogen', FS, 'end');
label(gLabels, 142, 530, 'Unused', FS, 'end');
label(gLabels, 142, 564, 'hydrogen', FS, 'end');
label(gLabels, 864, 273, 'Oxygen', FS, 'start');
label(gLabels, 864, 548, 'Water', FS, 'start');
label(gLabels, 396, 674, 'Anode', FS, 'middle');
label(gLabels, 512, 674, 'Proton', FS, 'middle');
label(gLabels, 512, 706, 'exchange', FS, 'middle');
label(gLabels, 512, 738, 'membrane', FS, 'middle');
label(gLabels, 640, 674, 'Cathode', FS, 'middle');
gLabels.line(404, 652, 420, 604).stroke({ color: '#000', width: 2 });
gLabels.line(506, 652, 500, 620).stroke({ color: '#000', width: 2 });
gLabels.line(628, 652, 601, 604).stroke({ color: '#000', width: 2 });

var annotTxt = label(gAnnot, 22, 48, '', 24, 'start', '#111');
halo(annotTxt);
gAnnot.opacity(0);

var ANNOT = {
  'idle': '',
  'h2-in': 'Fuel in:  H₂ flows along the anode channel',
  'oxidation': 'Anode:  2H₂  →  4H⁺ + 4e⁻',
  'transport': 'H⁺ through the membrane · e⁻ around through the load',
  'reduction': 'Cathode:  O₂ + 4H⁺ + 4e⁻  →  2H₂O'
};
var EMPH = {
  'idle': null,
  'h2-in': ['h2in', 'unused'],
  'oxidation': ['h2in', 'anodeE', 'protons'],
  'transport': ['anodeE', 'wire', 'protons', 'cathodeE'],
  'reduction': ['protons', 'cathodeE', 'o2', 'water', 'cathodeRxn', 'wire']
};

/* ---------- state application ---------- */
function positionAll() {
  var counts = {};
  KEYS.forEach(function (k) {
    counts[k] = state.rate <= 0 ? 0 : Math.ceil(S[k].n * (0.4 + 0.6 * state.rate / 100));
  });
  counts.cathodeRxn = state.rate <= 0 ? 0 : 1;
  particles.forEach(function (p) {
    var pt = p.path(p.t);
    p.g.transform({ translateX: pt.x, translateY: pt.y });
    p.g.opacity(p.idx < counts[p.s] ? 1 : 0);
  });
}

function applyPhase() {
  var em = EMPH[state.phase];
  KEYS.forEach(function (k) {
    S[k].g.opacity(!em ? 1 : (em.indexOf(k) >= 0 ? 1 : 0.16));
  });
  var txt = ANNOT[state.phase] || '';
  if (txt && !state.clean) { annotTxt.plain(txt); halo(annotTxt); gAnnot.opacity(1); }
  else { gAnnot.opacity(0); }
  membGlow.opacity(state.phase === 'transport' ? 0.95 : 0);
  var live = (state.phase === 'transport' || state.phase === 'reduction') && state.rate > 0;
  boltGlow.opacity(live ? 0.45 : 0);
  var btns = document.querySelectorAll('#phaseBtns button');
  for (var i = 0; i < btns.length; i++) {
    btns[i].className = (btns[i].getAttribute('data-ph') === state.phase) ? 'active' : '';
  }
  document.getElementById('cyclePhaseInput').value = state.phase;
}

function applyClean() {
  var d = state.clean ? C.darkClean : C.dark;
  var g = state.clean ? C.grayClean : C.gray;
  var sc = state.clean ? '#c9c9c9' : '#000';
  var sw = state.clean ? 2 : 3;
  darkEls.forEach(function (e) { e.fill(d).stroke({ color: sc, width: sw }); });
  circEls.forEach(function (e) { e.fill(d).stroke({ color: sc, width: sw }); });
  grayEls.forEach(function (e) { e.fill(g).stroke({ color: sc, width: sw }); });
  [anode, memb, cath].forEach(function (e) { e.stroke({ color: state.clean ? '#9a9a9a' : '#000', width: sw }); });
  gLabels.opacity(state.clean ? 0 : 1);
  buildArrows();
  applyPhase();
}

/* ---------- animation ---------- */
var lastTs = 0;
function frame(ts) {
  if (!lastTs) lastTs = ts;
  var dt = Math.min(0.06, (ts - lastTs) / 1000);
  lastTs = ts;
  if (state.running && state.rate > 0) {
    var k = 0.35 + 1.1 * state.rate / 100;
    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      if (p.v <= 0) continue;
      p.t += p.v * dt * k;
      while (p.t > 1) p.t -= 1;
    }
    positionAll();
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

/* ---------- control handlers ---------- */
function setPhase(ph) {
  state.phase = ph;
  if (ph === 'idle') {
    state.running = false;
    var cb = document.getElementById('flowAnimationInput');
    if (cb) cb.checked = false;
    particles.forEach(function (p) { p.t = p.t0; });
    positionAll();
  }
  applyPhase();
}
function toggle_flowAnimation(on) {
  state.running = !!on;
  lastTs = 0;
  if (on && state.phase === 'idle') { state.phase = 'h2-in'; applyPhase(); }
}
function update_h2FeedRate(v) {
  state.rate = +v;
  buildArrows();
  positionAll();
  applyPhase();
}
function toggle_labelMode(on) {
  state.clean = !!on;
  applyClean();
}
function showKeyInsight() {
  showPopup('The membrane does the trick',
    'Burning hydrogen in air releases the same energy as heat. In a fuel cell the two half-reactions are physically separated: the membrane lets H⁺ pass but blocks electrons, so the electrons can only reach the oxygen by travelling the long way round through the external load. That forced detour is the electric current.');
}

/* ---------- demo steps ---------- */
var steps = [
  { title: 'The three layers', narration: 'Meet the cell: a purple anode on the left, a blue proton exchange membrane in the middle, and a purple cathode on the right, all wired through a resistor labeled Electric power at the top. Nothing is moving yet.', state: { cyclePhase: 'idle', labelMode: 'Labeled diagram', h2FeedRate: 60 } },
  { title: 'Hydrogen arrives', narration: 'H₂ molecules flow in through the left channel and press against the anode surface; any molecule that doesn\'t react continues out the bottom-left as unused hydrogen.', state: { cyclePhase: 'h2-in', labelMode: 'Labeled diagram', h2FeedRate: 60 } },
  { title: 'Oxidation at the anode', narration: 'At the anode each H₂ splits: 2H₂ → 4H⁺ + 4e⁻. The protons enter the membrane while the electrons pile up in the electrode, unable to follow them.', state: { cyclePhase: 'oxidation', labelMode: 'Labeled diagram', h2FeedRate: 60 } },
  { title: 'Two separate paths', narration: 'The membrane conducts protons but blocks electrons, so the electrons are forced up and around through the external wire — that detour through the resistor is the electric power the cell delivers.', state: { cyclePhase: 'transport', labelMode: 'Labeled diagram', h2FeedRate: 60 } },
  { title: 'Reduction at the cathode', narration: 'Protons crossing the membrane meet the returning electrons and incoming O₂ at the cathode: O₂ + 4H⁺ + 4e⁻ → 2H₂O. Water drains out the lower right — the only byproduct.', state: { cyclePhase: 'reduction', labelMode: 'Labeled diagram', h2FeedRate: 60 } },
  { title: 'Throttle the fuel', narration: 'Cut the hydrogen feed and the inlet arrow thins, fewer protons cross, and the current arrows in the external circuit thin in lockstep — the power output tracks the fuel supply.', state: { cyclePhase: 'reduction', labelMode: 'Labeled diagram', h2FeedRate: 15 } },
  { title: 'Just the flows', narration: 'With the labels collapsed, the whole device reduces to two loops of charge: protons straight through the membrane, electrons the long way around through the load.', state: { cyclePhase: 'reduction', labelMode: 'Clean flow schematic', h2FeedRate: 80 } }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var st = steps[stepIdx].state;
  var rs = document.getElementById('h2FeedRateInput');
  rs.value = st.h2FeedRate;
  document.getElementById('h2FeedRateVal').value = st.h2FeedRate;
  update_h2FeedRate(+st.h2FeedRate);
  var clean = st.labelMode !== 'Labeled diagram';
  document.getElementById('labelModeInput').checked = clean;
  toggle_labelMode(clean);
  setPhase(st.cyclePhase);
  var run = st.cyclePhase !== 'idle';
  document.getElementById('flowAnimationInput').checked = run;
  toggle_flowAnimation(run);
  document.getElementById('demoNarration').textContent = steps[stepIdx].narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length + ' · ' + steps[stepIdx].title;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ---------- init ---------- */
buildArrows();
positionAll();
applyClean();
applyStep(0);

window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A hydrogen–oxygen fuel cell converts chemical energy directly into electricity by splitting the oxidation and reduction half-reactions across a proton-exchange membrane, forcing electrons through an external circuit while only protons cross the membrane, with water as the sole product.
KEY INSIGHT (what students should walk away understanding): The membrane's selectivity is the whole trick: by letting protons pass but not electrons, it forces the electrons to travel through an external circuit, turning a spontaneous hydrogen-burning reaction into usable electric current instead of heat.
DEMO STEPS: 7 guided steps — implement the step player in #ui

FULL BLUEPRINT:
