  <button data-ph="transport" onclick="setPhase('transport')">Transport</button>
  <button data-ph="reduction" onclick="setPhase('reduction')">Reduction</button>
</span>
<input id="cyclePhaseInput" type="hidden" value="idle">
<label><input id="flowAnimationInput" type="checkbox" onchange="toggle_flowAnimation(this.checked)"> Run continuous flow</label>
<label>H₂ feed rate: <output id="h2FeedRateVal">60</output><input id="h2FeedRateInput" type="range" min="0" max="100" step="5" value="60" oninput="document.getElementById('h2FeedRateVal').value=this.value;update_h2FeedRate(+this.value)"></label>
