// @FIGURE_CODE_BEGIN
var W = 960, H = 760;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

var C = {
  dark: '#333333', darkClean: '#e8e8e8',
  gray: '#c8c8c8', grayClean: '#f3f3f3',
  yellow: '#ffe600', tan: '#d9a441'
};

var state = { phase: 'idle', rate: 60, clean: false, running: false };

/* ---------- gradients ---------- */
var gWhite = draw.gradient('radial', function (add) { add.stop(0, '#ffffff'); add.stop(1, '#b4b8c4'); });
gWhite.attr({ fx: 0.35, fy: 0.3 });
var gRed = draw.gradient('radial', function (add) { add.stop(0, '#ff8a8a'); add.stop(1, '#c00b0b'); });
gRed.attr({ fx: 0.35, fy: 0.3 });
var gPurple = draw.gradient('linear', function (add) {
  add.stop(0, '#b94cee'); add.stop(0.5, '#a428e0'); add.stop(1, '#8d13cc');
});
gPurple.from(0, 0).to(1, 0);
var gBlue = draw.gradient('linear', function (add) {
  add.stop(0, '#5c88ff'); add.stop(0.5, '#3f6ff0'); add.stop(1, '#2d54dc');
});
gBlue.from(0, 0).to(1, 0);

/* ---------- layers ---------- */
var gBase = draw.group();
var gCirc = draw.group();
var gStream = draw.group();
var gGlow = draw.group();
var gLabels = draw.group();
var gAnnot = draw.group();

/* ---------- helpers ---------- */
function halo(t) { t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' }); return t; }
function label(parent, x, y, str, size, anchor, fill) {
  var t = parent.plain(str);
  t.font({ family: 'Helvetica, Arial, sans-serif', size: size, anchor: anchor || 'middle' });
  t.fill(fill || '#000');
  t.attr({ x: x, y: y });
  return t;
}
function arrow(g, x1, y1, x2, y2, w, col) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy);
  if (L < 1 || w <= 0) return;
  var ux = dx / L, uy = dy / L, hl = Math.min(2.3 * w, L * 0.6), hw = 1.75 * w;
  var bx = x2 - ux * hl, by = y2 - uy * hl;
  g.line(x1, y1, bx, by).stroke({ color: col, width: w, linecap: 'butt' });
  g.polygon([[x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]).fill(col);
}
function lin(x1, y1, x2, y2) { return function (t) { return { x: x1 + (x2 - x1) * t, y: y1 + (y2 - y1) * t }; }; }
function polyP(pts) {
  var segs = [], tot = 0, i;
  for (i = 1; i < pts.length; i++) { var L = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); segs.push(L); tot += L; }
  return function (t) {
    var d = Math.max(0, Math.min(1, t)) * tot, k = 0;
    while (k < segs.length && d > segs[k]) { d -= segs[k]; k++; }
    if (k >= segs.length) return { x: pts[pts.length - 1][0], y: pts[pts.length - 1][1] };
    var f = segs[k] ? d / segs[k] : 0;
    return { x: pts[k][0] + (pts[k + 1][0] - pts[k][0]) * f, y: pts[k][1] + (pts[k + 1][1] - pts[k][1]) * f };
  };
}
function hoverable(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
}

/* ---------- housing ---------- */
var darkEls = [], grayEls = [], circEls = [];

var grayL = gBase.rect(148, 405).move(232, 195).fill(C.gray).stroke({ color: '#000', width: 3 });
var grayR = gBase.rect(148, 405).move(620, 195).fill(C.gray).stroke({ color: '#000', width: 3 });
grayEls.push(grayL, grayR);

var leftPts = [[150, 232], [380, 232], [380, 570], [150, 570], [150, 508], [292, 508], [292, 294], [150, 294]];
var rightPts = leftPts.map(function (p) { return [1000 - p[0], p[1]]; });
var darkL = gBase.polygon(leftPts).fill(C.dark).stroke({ color: '#000', width: 3, linejoin: 'miter' });
var darkR = gBase.polygon(rightPts).fill(C.dark).stroke({ color: '#000', width: 3, linejoin: 'miter' });
