}
function arrow(g, x1, y1, x2, y2, w, col) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy);
  if (L < 1 || w <= 0) return;
  var ux = dx / L, uy = dy / L, hl = Math.min(2.3 * w, L * 0.6), hw = 1.75 * w;
  var bx = x2 - ux * hl, by = y2 - uy * hl;
  g.line(x1, y1, bx, by).stroke({ color: col, width: w, linecap: 'butt' });
  g.polygon([[x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]).fill(col);
}
function lin(x1, y1, x2, y2) { return function (t) { return { x: x1 + (x2 - x1) * t, y: y1 + (y2 - y1) * t }; }; }
function polyP(pts) {
  var segs = [], tot = 0, i;
  for (i = 1; i < pts.length; i++) { var L = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); segs.push(L); tot += L; }
  return function (t) {
    var d = Math.max(0, Math.min(1, t)) * tot, k = 0;
    while (k < segs.length && d > segs[k]) { d -= segs[k]; k++; }
    if (k >= segs.length) return { x: pts[pts.length - 1][0], y: pts[pts.length - 1][1] };
    var f = segs[k] ? d / segs[k] : 0;
    return { x: pts[k][0] + (pts[k + 1][0] - pts[k][0]) * f, y: pts[k][1] + (pts[k + 1][1] - pts[k][1]) * f };
  };
}
