/* ---------- animation ---------- */
var lastTs = 0;
function frame(ts) {
  if (!lastTs) lastTs = ts;
  var dt = Math.min(0.06, (ts - lastTs) / 1000);
  lastTs = ts;
  if (state.running && state.rate > 0) {
    var k = 0.35 + 1.1 * state.rate / 100;
    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      if (p.v <= 0) continue;
      p.t += p.v * dt * k;
      while (p.t > 1) p.t -= 1;
    }
    positionAll();
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

/* ---------- control handlers ---------- */
function setPhase(ph) {
  state.phase = ph;
  if (ph === 'idle') {
    state.running = false;
    var cb = document.getElementById('flowAnimationInput');
    if (cb) cb.checked = false;
    particles.forEach(function (p) { p.t = p.t0; });
    positionAll();
  }
  applyPhase();
}
function toggle_flowAnimation(on) {
  state.running = !!on;
  lastTs = 0;
  if (on && state.phase === 'idle') { state.phase = 'h2-in'; applyPhase(); }
